IF OBJECT_ID(N'[higherlogic_vanilla].[EscalationLog]', N'U') IS NULL
CREATE TABLE [higherlogic_vanilla].[EscalationLog] (
    [pagination_continuation] NVARCHAR(812) NULL,
    [pagination_has_more_items] NVARCHAR(MAX) NULL,
    [mj_e2e_custom_attr] NVARCHAR(812) NULL,
    [pagination_page_size] NVARCHAR(MAX) NULL,
    [recordType] NVARCHAR(812) NULL,
    [action] NVARCHAR(812) NULL,
    [recordUserID] NVARCHAR(MAX) NULL,
    [pagination_page_number] NVARCHAR(MAX) NULL,
    [pagination_object_count] NVARCHAR(MAX) NULL,
    [escalationLogID] NVARCHAR(450) NULL,
    [insertUserID] NVARCHAR(MAX) NULL,
    [reasons] NVARCHAR(MAX) NULL,
    [data] NVARCHAR(812) NULL,
    [recordID] NVARCHAR(MAX) NULL,
    [authorNotificationMessage] NVARCHAR(812) NULL,
    [pagination_page_count] NVARCHAR(MAX) NULL,
    [dateInserted] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncStatus] NVARCHAR(50) NOT NULL DEFAULT 'Active',
    [__mj_integration_LastSyncedAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastSyncedSnapshot] NVARCHAR(MAX) NULL,
    [__mj_integration_SyncMessage] NVARCHAR(MAX) NULL,
    [__mj_integration_ContentHash] NVARCHAR(64) NULL,
    [__mj_integration_CustomOverflow] NVARCHAR(MAX) NULL,
    [__mj_integration_ExternalVersion] NVARCHAR(255) NULL,
    [__mj_integration_LastSeenModifiedValue] NVARCHAR(255) NULL,
    [__mj_integration_LastReconciledAt] DATETIMEOFFSET NULL,
    [__mj_integration_LastWriterDirection] NVARCHAR(10) NULL,
    [__mj_integration_IsTombstoned] BIT NOT NULL DEFAULT 0,
    [__mj_integration_DeletedDetectedAt] DATETIMEOFFSET NULL
);

