    @value = N'SHA-256 (hex) of the last-synced external field values. Lets the engine detect changes and skip re-loading/re-writing unchanged records for sources that have no usable watermark (e.g. YourMembership, which re-fetches every record each sync).',
    @level0type = N'SCHEMA', @level0name = 'higherlogic_vanilla',
    @level1type = N'TABLE', @level1name = 'Keyword',
    @level2type = N'COLUMN', @level2name = '__mj_integration_ContentHash';

