EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Backend staging (system) column: JSON of source fields a record returned that have no field map yet — the extra keys this table has no column for. A post-sync Runtime-Schema-Updation pass promotes pervasive keys to real columns and clears them here. Not user-facing metadata; transient until promotion.',
    @level0type = N'SCHEMA', @level0name = 'higherlogic_vanilla',
    @level1type = N'TABLE', @level1name = 'Keyword',
    @level2type = N'COLUMN', @level2name = '__mj_integration_CustomOverflow';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N'higherlogic_vanilla', N'TABLE', N'Keyword', N'COLUMN', N'__mj_integration_ExternalVersion'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'The external system’s version/etag/modified token for the last-synced state, used for optimistic-concurrency (OCC) detection on bidirectional push. Null when the source exposes no version token.',
