    @level1type = N'TABLE', @level1name = 'Keyword',
    @level2type = N'COLUMN', @level2name = '__mj_integration_ExternalVersion';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N'higherlogic_vanilla', N'TABLE', N'Keyword', N'COLUMN', N'__mj_integration_LastSeenModifiedValue'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'The watermark / last-modified value observed for THIS record on the last sync (per-record, independent of the entity-map-level CompanyIntegrationSyncWatermark).',
